import re, sys
from xml.dom import minidom

path = "unpacked/word/document.xml"
dom = minidom.parse(path)

ns = {"w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"}
W = ns["w"]

def local(tag):
    return tag.split("}")[-1]

paras = dom.getElementsByTagNameNS(W, "p")
print("Total paragraphs:", len(paras))

def para_text(p):
    texts = []
    for t in p.getElementsByTagNameNS(W, "t"):
        texts.append(t.firstChild.data if t.firstChild else "")
    return "".join(texts)

for i, p in enumerate(paras):
    pPr = p.getElementsByTagNameNS(W, "pPr")
    style = None
    if pPr:
        for ps in pPr[0].getElementsByTagNameNS(W, "pStyle"):
            if ps.hasAttribute("w:val"):
                style = ps.getAttribute("w:val")
    text = para_text(p).strip()
    if style and (style.lower().startswith("heading") or style.lower() == "title" or "head" in style.lower()):
        print(f"para[{i}] style={style!r} text={text[:80]!r}")

